#!/usr/bin/env node
import path from 'node:path';
import { fileURLToPath } from 'node:url';

import { finalizeRigModel } from '../../scripts/finalize-rig-common.mjs';
import { prepareCreatureControlDefs } from './prepare-control-defs.mjs';

function parseArgs(argv) {
  const args = { creature: '', resourceRoot: '' };
  for (let index = 0; index < argv.length; index += 1) {
    if (argv[index] === '--creature') {
      args.creature = argv[index + 1] || '';
      index += 1;
    } else if (argv[index] === '--resource-root') {
      args.resourceRoot = argv[index + 1] || '';
      index += 1;
    }
  }
  if (!args.creature || !args.resourceRoot) {
    throw new Error('Usage: finalize-rig.mjs --creature <entry-name> --resource-root assets/module/<resource-id>');
  }
  return args;
}

export async function finalizeCreatureRig(options) {
  const prepared = prepareCreatureControlDefs({ creature: options.creature });
  if (prepared.validation?.ok !== true) {
    throw new Error(`Reference skeleton validation failed for creature entry "${options.creature}".`);
  }
  if (!prepared.metaSkeleton || !Array.isArray(prepared.controlDefs) || prepared.controlDefs.length === 0) {
    throw new Error(`Reference skeleton did not produce a complete rig for creature entry "${options.creature}".`);
  }
  return finalizeRigModel({
    expectedControlNodes: prepared.controlDefs.map(definition => ({
      name: definition.name,
      ...(definition.parentName ? { parentName: definition.parentName } : {}),
    })),
    resourceRoot: options.resourceRoot,
    rigFamily: 'creature',
    skeleton: prepared.metaSkeleton,
  });
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  const result = await finalizeCreatureRig(args);
  process.stdout.write(`${JSON.stringify({ ...result, creatureEntry: args.creature }, null, 2)}\n`);
}

const isDirectExecution = process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isDirectExecution) {
  main().catch(error => {
    console.error(error instanceof Error ? error.message : String(error));
    process.exitCode = 1;
  });
}

