  const up = Number(bounds.up) || 0;
  const forward = Number(bounds.forward) || 0;

  if (right <= 0 || up <= 0 || forward <= 0) {
    return null;
  }

  const boundsRoot = new THREE.Group();
  boundsRoot.name = `${options.rootName || 'creature_ref'}__bounds`;

  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(right * 2, up * 2, forward * 2),
    new THREE.MeshBasicMaterial({
      color: options.boundsColor ?? 0xffc857,
      transparent: true,
      opacity: options.boundsOpacity ?? 0.12,
      wireframe: true,
