  return {
    name: node.name,
    parentName: node.parentName || undefined,
    pos: Array.isArray(node.pos) ? [...node.pos] : [0, 0, 0],
    rot: Array.isArray(node.rot) ? [...node.rot] : [0, 0, 0, 1],
    scale: Array.isArray(node.scale) ? [...node.scale] : [1, 1, 1],
    rotationMode: node.rotationMode || inferRotationMode(node.rot),
  };
