export function createCreatureControlNodeDefs(options) {
  const creatureName = normalizeText(options?.creatureName) || DEFAULT_CREATURE_NAME;
  const entry = options?.entry || selectCreatureSkeletonEntry(options?.manifestListText || '{}', creatureName);
  const manifestData = options?.manifestData || parseSkeletonManifestData(options?.manifestDataText || '{}');
  const sourceTree = options?.sourceTree || createBoneTree(manifestData, options || {}, entry);
  const { sceneTree } = buildSceneTree(sourceTree, options || {});
  return sceneTree.nodes.map(cloneNodeDefinition);
}

export function selectCreatureSkeletonEntry(manifestListText, creatureName = DEFAULT_CREATURE_NAME) {
  const manifest = parseSkeletonManifestList(manifestListText);
  const entry = findSkeletonManifestEntryByName(manifest, creatureName);
  if (!entry) {
    throw new Error(`Skeleton manifest entry not found for creature: ${normalizeText(creatureName) || '<empty>'}`);
  }
  return entry;
}

export function createCreatureReferenceRoot(options) {
  const THREE = getThreeNamespace(options);
  const manifestData = options.manifestData || parseSkeletonManifestData(options.manifestDataText || '{}');
  const sourceTree = options.sourceTree || createBoneTree(manifestData, options, options.entry);
  const { sceneTree } = buildSceneTree(sourceTree, options);
  const childMap = getChildMap(sceneTree.nodes);
  const hiddenBoneSet = new Set(Array.isArray(manifestData?.NoMeshBones) ? manifestData.NoMeshBones.map(normalizeText) : []);

  const root = new THREE.Group();
  root.name = options.rootName || `${normalizeText(options.creatureName) || DEFAULT_CREATURE_NAME}_creature_ref`;
  root.userData.creatureReference = {
    creatureName: normalizeText(options.creatureName) || DEFAULT_CREATURE_NAME,
    controller: normalizeText(manifestData?.controller) || undefined,
    avatar: normalizeText(manifestData?.avatar) || undefined,
    bounds: manifestData?.bounds || undefined,
  };

  const boneMap = new Map();
  for (const node of sceneTree.nodes) {
    const boneObject = new THREE.Group();
    boneObject.name = node.name;
    boneObject.position.set(...node.pos);
    boneObject.scale.set(...(node.scale || [1, 1, 1]));

    const rotationMode = node.rotationMode || inferRotationMode(node.rot);
