export function buildCreatureReference(options) {
  const creatureName = normalizeText(options?.creatureName) || DEFAULT_CREATURE_NAME;
  const entry = options?.entry || selectCreatureSkeletonEntry(options?.manifestListText || '{}', creatureName);
  const manifestData = options?.manifestData || parseSkeletonManifestData(options?.manifestDataText || '{}');
  const sourceTree = createBoneTree(manifestData, options || {}, entry);
  const { transformedTree, sceneTree } = buildSceneTree(sourceTree, options || {});
  const rootResult = createCreatureReferenceRoot({
    ...options,
    creatureName,
    entry,
    manifestData,
    sourceTree,
  });

  rootResult.root.userData.creatureReference.entry = entry;
  rootResult.root.userData.creatureReference.skeleton = entry.skeleton;
  rootResult.root.userData.creatureReference.script = entry.script || undefined;

  return {
    entry,
    manifestData,
    sourceTree,
    transformedTree,
    sceneTree,
    ...rootResult,
  };
}

export function createCreatureControlDefsJs(options) {
  const defs = createCreatureControlNodeDefs(options);
  const literal = defs
    .map(node => {
      const parentLiteral = node.parentName ? `'${node.parentName}'` : 'null';
      const rotationModeComment = node.rotationMode && node.rotationMode !== 'quaternion'
        ? `, '${node.rotationMode}'`
